def agent(obs):
    step = obs.get("step")
    if step is None:
        step = obs["day"] * 24 + obs["hour"]
    if step < len(_A):
        a = _A[step]
        me = obs["farms"][obs["player"]]
        n = len(me.get("hands", []))
        return {"farmer": a["farmer"], "hands": (a["hands"] + [["PASS"]] * n)[:n],
                "market": a["market"]}
    return {"farmer": ["PASS"], "hands": [["PASS"]] * len(obs["farms"][obs["player"]].get("hands", [])), "market": []}
